package l1j.server.server.model.network.core;public class CAsyncSendConstBuffer implements AutoCloseable {public static int opens,closes;final byte[] wire;public CAsyncSendConstBuffer(byte[] wire,int id,int limit){this.wire=wire;opens++;}public boolean apply(CUserSocket target,int id){if(target.fail)throw new IllegalStateException("injected");if(!target.shared)return false;target.wires.add(wire.clone());return true;}public void close(){closes++;}}
